$(function() {

    loadDefaultValue();

    $(document).on("keyup", ".get-guest-data", function (e) {
        e.preventDefault();
        var obj = $('#cell');
        var form = obj.closest('form');
        var cell = obj.val();
        form[0].reset();
        obj.val(cell);
        if (cell.length > 10) {
            var link = obj.data('link');
            $.ajax({
                type: "GET",
                url: link,
                global: false,
                data: {'cell': cell},
                dataType: 'JSON',
                success: function (result) {
                    if (result.status == '1') {
                        var data = result.data;
                        $('#sec_cell').val(data.sec_cell);
                        $('#emergency_contact').val(data.emergency_contact);
                        $('#nameprefix').val(data.nameprefix);
                        $('#firstname').val(data.firstname);
                        $('#lastname').val(data.lastname);
                        $('#email').val(data.email);
                        $('#birthdate').val(data.birthdate);
                        $('#marriagedate').val(data.marriagedate);
                        $('#nationality').val(data.nationality);
                        $('#nid').val(data.nid);
                        $('#passport').val(data.passport);
                        $('#passportdateplace').val(data.passportdateplace);
                        $('#presentcountryid').val(data.presentcountryid);
                        $('#presentcity').val(data.presentcity);
                        $('#presentaddress').val(data.presentaddress);
                        $('#permanentcountryid').val(data.permanentcountryid);
                        $('#permanentcity').val(data.permanentcity);
                        $('#permanentaddress').val(data.permanentaddress);
                        $('#profession').val(data.profession);
                        $('#company').val(data.company);
                        $('#market').val(data.market);
                        $('#source').val(data.source);
                        $('#referenceid').val(data.referenceid);
                        $('#preference').val(data.preference);
                        sameAddress();
                    }
                },
                error: function (data) {
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        } else {
            return false;
        }
    });

    $(document).on("change keyup", "#sameaspresent, #presentcountryid, #presentcity, #presentaddress", function (e) {
        sameAddress();
    });

    $(document).on("change keyup", "#permanentcountryid, #permanentcity, #permanentaddress", function (e) {
        $('#sameaspresent').prop('checked', false);
    });

    sameAddress();
});


$(function() {
    $('#birthdate').datepicker({
        dateFormat: 'dd/mm/yy',
        maxDate:0,
        changeMonth: true,
        changeYear: true,
        yearRange: "-100:+0"
    });

    $( "#birthdate" ).inputmask({ alias: "datetime", inputFormat: "dd/mm/yyyy", "placeholder": "DD/MM/YYYY", "mode": "numeric" }).attr('autocomplete','off');


    $('#marriagedate').datepicker({
        dateFormat: 'dd/mm/yy',
        maxDate:0,
        changeMonth: true,
        changeYear: true,
        yearRange: "-100:+0"
    });

    $( "#marriagedate" ).inputmask({ alias: "datetime", inputFormat: "dd/mm/yyyy", "placeholder": "DD/MM/YYYY", "mode": "numeric" }).attr('autocomplete','off');
});


function sameAddress(){
    if($('#sameaspresent').is(':checked')){
        $('#permanentcountryid').attr('data-hvalue',$('#permanentcountryid').val());
        $('#permanentcountryid').val($('#presentcountryid').val());

        $('#permanentcity').attr('data-hvalue',$('#permanentcity').val());
        $('#permanentcity').val($('#presentcity').val());

        $('#permanentaddress').attr('data-hvalue',$('#permanentaddress').val());
        $('#permanentaddress').val($('#presentaddress').val());
    } else {
        $('#permanentcountryid').val($('#permanentcountryid').data('hvalue'));
        $('#permanentcity').val($('#permanentcity').data('hvalue'));
        $('#permanentaddress').val($('#permanentaddress').data('hvalue'));
    }

    $(".chosen").trigger('chosen:updated');
}
